import {useTranslation} from 'react-i18next';
import {
  Content,
  INotification,
  ParamEntry,
} from '../../../../model/interface/notification.interface';
import React from 'react';
import RenderHtml from 'react-native-render-html';
import {stylesHTML} from './helper';
import {TouchableOpacity, View} from 'react-native';
import TextCM from '../../../components/Text';
import styles from './styles';
import {Font} from '../../../../constants';
import {Badge, Divider} from 'react-native-paper';
import {Icon} from '@ui-kitten/components';
import {isEmpty} from 'lodash';
interface NotificationProps {
  notiItem: INotification;
  tab: 'read' | 'unread';
  markAsReaded: (id: number) => void;
}

export default function NotificationCard({
  notiItem,
  tab,
  markAsReaded,
}: NotificationProps) {
  const {t} = useTranslation();
  const getAttrKey = (
    paramEntry: Record<string, any> | null | undefined,
  ): string | undefined => {
    if (
      paramEntry &&
      typeof paramEntry === 'object' &&
      Object.keys(paramEntry).length > 0
    ) {
      const key = Object.keys(paramEntry)[0];
      return key;
    }
    return undefined;
  };

  const getAttr = (key: string): string => {
    if (key === 'name') {
      return 'board.name';
    } else if (key === 'priority') {
      return 'task.priority';
    } else if (key === 'tags') {
      return 'task.tag';
    } else if (key === 'startDate') {
      return 'task.start-date';
    } else if (key === 'dueDate') {
      return 'task.due-date';
    } else if (key === 'description') {
      return 'task.description';
    } else if (key === 'remindDate') {
      return 'Thời gian nhắc nhở';
    } else if (key === 'status') {
      return 'task.status';
    } else if (key === 'rating') {
      return 'task.rate';
    } else if (key === 'rateDetails') {
      return 'task.rateComment';
    }

    return '';
  };

  const getHostEnv = (): string => {
    return `127.0.0.1://3000/etask`;
  };
  const getAuthority = (
    name: 'all' | 'comment' | 'read' | 'edit',
  ): string | null => {
    if (name === 'all') {
      return 'shared.selectAuth.all';
    } else if (name === 'comment') {
      return 'shared.selectAuth.comment';
    } else if (name === 'read') {
      return 'shared.selectAuth.read';
    } else if (name === 'edit') {
      return 'shared.selectAuth.edit';
    }
    return null;
  };
  const getPathNoti = (noti: INotification) => {
    let params = '',
      url = '';

    if (
      (noti.content as Content)?.parentTaskDto &&
      (noti.content as Content)?.taskDto
    ) {
      params += `taskId=${
        (noti.content as Content)?.parentTaskDto?.id
      }&subTaskId=${(noti.content as Content)?.taskDto?.id}`;
    } else if ((noti.content as Content)?.taskDto) {
      params += `taskId=${(noti.content as Content)?.taskDto?.id}`;
    }

    if (
      noti.type === 'ASSIGNEE_UPDATE_TASK_STATUS_IN_MY_LIST' ||
      noti.type === 'ASSIGN_USER_AS_COORDINATOR_OWNER' ||
      noti.type === 'REMOVE_TASK_LIST_COORDINATOR_OWNER' ||
      noti.type === 'LIST_OWNER_INFO_UPDATED' ||
      noti.type === 'LIST_OWNER_DELETED' ||
      noti.type === 'LIST_OWNER_ADD_INFO' ||
      noti.type === 'USER_EDITED_LIST_INFO' ||
      noti.type === 'USER_DELETED_LIST' ||
      noti.type === 'USER_ADD_INFO_TO_LIST' ||
      noti.type === 'TASK_PERMISSION_UPDATED' ||
      noti.type === 'TASK_PERMISSION_DELETED' ||
      noti.type === 'TASK_PERMISSION_ADD_INFO' ||
      noti.type === 'COORDINATOR_ADDED_NEW_TASK' ||
      noti.type === 'COORDINATOR_UPDATED_TASK_INFO' ||
      noti.type === 'TEMPLATE_PERMISSION_EDITED' ||
      noti.type === 'TEMPLATE_PERMISSION_DELETED' ||
      noti.type === 'TEMPLATE_PERMISSION_ADD_INFO' ||
      // && accountService.getAccount().email === noti.createdBy
      (noti.type === 'NOTIFY_COMMENT' &&
        (noti.content as Content)?.commentNotifyDto?.users?.[0]?.role ===
          'owner')
    ) {
      url = `${getHostEnv()}/manage/my-task/detail/${
        (noti.content as Content)?.listTaskDTO?.id
      }`;
    } else if (
      noti.type === 'APPROVE_ASSIGN' ||
      noti.type === 'ASSIGN_USER_AS_TASK_APPROVED' ||
      noti.type === 'TASK_NEEDS_APPROVED' ||
      noti.type === 'TASK_PENDING_APPROVED' ||
      (noti.type === 'NOTIFY_COMMENT' &&
        (noti.content as Content)?.commentNotifyDto?.users?.[0]?.role ===
          'approver')
    ) {
      url = `${getHostEnv()}/manage/approved-task/detail/${
        (noti.content as Content)?.listTaskDTO?.id
      }`;
    } else if (
      noti.type === 'TASK_RATING_ADD' ||
      noti.type === 'TASK_RATING_UPDATED' ||
      noti.type === 'TASK_COMMENT_ADD' ||
      noti.type === 'TASK_COMMENT_UPDATED' ||
      noti.type === 'ASSIGN_TASK_LIST_TO_USER' ||
      noti.type === 'ASSIGN_TASK_LIST_TO_GROUP' ||
      noti.type === 'ASSIGN_TASK_LIST_TO_ORG' ||
      noti.type === 'ASSIGN_TASK_TO_USER' ||
      noti.type === 'ASSIGN_TASK_TO_GROUP' ||
      noti.type === 'ASSIGN_TASK_TO_ORG' ||
      noti.type === 'ASSIGN_SUBTASK_TO_USER' ||
      noti.type === 'ASSIGN_SUBTASK_TO_GROUP' ||
      noti.type === 'ASSIGN_SUBTASK_TO_ORG' ||
      noti.type === 'TASK_REMINDER' ||
      noti.type === 'TASK_REMINDER_NO_DATE' ||
      noti.type === 'TASK_OVERDUE_REMINDER' ||
      noti.type === 'TASK_APPROVED' ||
      ((noti.type === 'LIST_OWNER_INFO_UPDATED' ||
        noti.type === 'LIST_OWNER_DELETED' ||
        noti.type === 'LIST_OWNER_ADD_INFO' ||
        noti.type === 'USER_EDITED_LIST_INFO' ||
        noti.type === 'USER_DELETED_LIST' ||
        noti.type === 'USER_ADD_INFO_TO_LIST' ||
        noti.type === 'LIST_OWNER_UPDATED_TASK_INFO' ||
        noti.type === 'LIST_OWNER_DELETED_TASK' ||
        noti.type === 'TASK_OWNER_ADD_INFO' ||
        noti.type === 'TASK_PERMISSION_UPDATED' ||
        noti.type === 'TASK_PERMISSION_DELETED' ||
        noti.type === 'TASK_PERMISSION_ADD_INFO' ||
        noti.type === 'COORDINATOR_ADDED_NEW_TASK' ||
        noti.type === 'COORDINATOR_UPDATED_TASK_INFO' ||
        noti.type === 'TEMPLATE_OWNER_UPDATED' ||
        noti.type === 'TEMPLATE_OWNER_DELETED' ||
        noti.type === 'TEMPLATE_OWNER_ADD_INFO' ||
        noti.type === 'TEMPLATE_PERMISSION_EDITED' ||
        noti.type === 'TEMPLATE_PERMISSION_DELETED' ||
        noti.type === 'TEMPLATE_PERMISSION_ADD_INFO') &&
        ((noti.content as Content)?.assignGroupDto ||
          (noti.content as Content)?.assignOrgDto ||
          (noti.content as Content)?.assignTaskDto)) ||
      (noti.type === 'NOTIFY_COMMENT' &&
        (noti.content as Content)?.commentNotifyDto?.users?.[0]?.role ===
          'assign')
    ) {
      url = `${getHostEnv()}/manage/assign-task/detail/${
        (noti.content as Content)?.listTaskDTO?.id
      }`;
    } else if (
      noti.type === 'SHARE_TASK_LIST_TO_USER' ||
      noti.type === 'SHARE_TASK_LIST_TO_GROUP' ||
      noti.type === 'SHARE_TASK_LIST_TO_ORG' ||
      noti.type === 'SHARE_TASK_TO_USER' ||
      noti.type === 'SHARE_TASK_TO_GROUP' ||
      noti.type === 'SHARE_TASK_TO_ORG' ||
      ((noti.type === 'LIST_OWNER_INFO_UPDATED' ||
        noti.type === 'LIST_OWNER_DELETED' ||
        noti.type === 'LIST_OWNER_ADD_INFO' ||
        noti.type === 'USER_EDITED_LIST_INFO' ||
        noti.type === 'USER_DELETED_LIST' ||
        noti.type === 'USER_ADD_INFO_TO_LIST' ||
        noti.type === 'LIST_OWNER_UPDATED_TASK_INFO' ||
        noti.type === 'LIST_OWNER_DELETED_TASK' ||
        noti.type === 'TASK_OWNER_ADD_INFO' ||
        noti.type === 'TASK_PERMISSION_UPDATED' ||
        noti.type === 'TASK_PERMISSION_DELETED' ||
        noti.type === 'TASK_PERMISSION_ADD_INFO' ||
        noti.type === 'COORDINATOR_ADDED_NEW_TASK' ||
        noti.type === 'COORDINATOR_UPDATED_TASK_INFO' ||
        noti.type === 'TEMPLATE_OWNER_UPDATED' ||
        noti.type === 'TEMPLATE_OWNER_DELETED' ||
        noti.type === 'TEMPLATE_OWNER_ADD_INFO' ||
        noti.type === 'TEMPLATE_PERMISSION_EDITED' ||
        noti.type === 'TEMPLATE_PERMISSION_DELETED' ||
        noti.type === 'TEMPLATE_PERMISSION_ADD_INFO') &&
        (noti.content as Content)?.taskShareInternal) ||
      (noti.type === 'NOTIFY_COMMENT' &&
        (noti.content as Content)?.commentNotifyDto?.users?.[0]?.role ===
          'share')
    ) {
      url = `${getHostEnv()}/manage/authority-task/detail/${
        (noti.content as Content)?.listTaskDTO?.id
      }`;
    } else if (
      noti.type === 'SHARE_TEMPALTE_TASK_LIST_TO_USER' ||
      noti.type === 'SHARE_TEMPALTE_TASK_LIST_TO_GROUP' ||
      noti.type === 'SHARE_TEMPALTE_TASK_LIST_TO_ORG'
    ) {
      url = `${getHostEnv()}/manage/authority-template/detail/${
        (noti.content as Content)?.listTaskDTO?.id
      }`;
    } else if (
      noti.type === 'ASSIGN_USER_AS_COORDINATOR' ||
      noti.type === 'REMOVE_TASK_LIST_COORDINATOR'
    ) {
      url = `${getHostEnv()}/manage/coordination-task/detail/${
        (noti.content as Content)?.listTaskDTO?.id
      }`;
    }

    return `${url}${params ? '?' + params : ''}`;
  };

  const notiContent = notiItem.content as Content;
  const isTask = !!notiContent.taskDto;
  let key = getAttrKey(
    isTask
      ? notiContent.taskDto?.paramEntry
      : notiContent.listTaskDTO?.paramEntry,
  );
  let oldValueTrans: string = '';
  let newValueTrans: string = '';
  const paramEntrySource: ParamEntry | null = isTask
    ? notiContent?.taskDto?.paramEntry
    : notiContent?.listTaskDTO?.paramEntry;
  let oldValue: any = undefined;
  let newValue: any = undefined;
  // 2. Chỉ truy cập bằng key nếu key là string và nguồn dữ liệu tồn tại
  if (key !== undefined && paramEntrySource) {
    // Lúc này, TypeScript biết key là string và paramEntrySource không phải null/undefined
    const entryData = paramEntrySource[key]; // Truy cập vào object con { old: ..., new: ... }
    // Dùng optional chaining (?) để truy cập an toàn vào old/new phòng trường hợp entryData không có các thuộc tính đó
    oldValue = entryData?.old;
    newValue = entryData?.new;
  }
  if (isTask && notiContent.taskDto?.param) {
    const params = JSON.parse(notiContent.taskDto?.param || '');
    if (params.newStatusType === 'custom') {
      newValue = params.newStatus;
    } else {
      newValueTrans = 'board.status-' + params.newStatus;
    }
    if (params.oldStatusType === 'custom') {
      oldValue = params.oldStatus;
    } else {
      oldValueTrans = 'board.status-' + params.oldStatus;
    }
  }

  const iconName =
    notiContent.createdBy !== 'system' ? 'people-outline' : 'settings-outline';

  const handelPressNoti = (id: number) => {
    markAsReaded(id);
  };
  const convertTime = (isoString: string) => {
    const date = new Date(isoString);
    const day = ('0' + date.getUTCDate()).slice(-2);
    const month = ('0' + (date.getUTCMonth() + 1)).slice(-2);
    const year = date.getUTCFullYear();
    const hours = ('0' + date.getUTCHours()).slice(-2);
    const minutes = ('0' + date.getUTCMinutes()).slice(-2);
    return `${day}/${month}/${year} ${hours}:${minutes}`;
  };

  return (
    <TouchableOpacity
      style={styles.ctnMain}
      onPress={() => handelPressNoti(notiItem.id)}>
      <View style={styles.ctnIcon}>
        <Icon width={20} height={20} fill={'#39ac6c'} name={iconName} />
        {tab === 'unread' && <Badge size={10} style={styles.badge}></Badge>}
      </View>
      <View style={{flex: 1, rowGap: 10}}>
        <TextCM>
          <RenderHtml
            source={{
              html: t(`NT.${notiItem.type}`, {
                id: notiItem.id,
                path: getPathNoti(notiItem),
                message: `navbar.notify.${notiItem.type}`,
                name: notiContent?.taskDto?.name,
                taskName: notiContent?.parentTaskDto?.name,
                listTaskName: notiContent?.listTaskDTO?.name,
                createdBy: notiContent.createdBy,
                createdDate: notiContent.createdDateNotify?.toString(),
                aclName: getAuthority(notiContent?.taskShareInternal?.aclName),
                aclNameKey: notiContent?.taskShareInternal?.aclName,
                orgName: notiContent?.assignOrgDto?.orgName,
                groupName:
                  notiContent?.assignGroupDto?.groupName ||
                  notiContent?.taskShareInternal?.groupName,
                attr:
                  !isEmpty(getAttr(key || '')) && t(`NT.${getAttr(key || '')}`),
                oldValue: oldValue
                  ? oldValue
                  : oldValueTrans && t(`NT.${oldValueTrans}`),
                newValue: newValue
                  ? newValue
                  : newValueTrans && t(`NT.${newValueTrans}`),
                coordinator: notiContent?.assignTaskDto?.assignName,
                rating: notiContent?.taskDto?.rating,
                type: notiItem.type,
                dueDate: notiContent?.taskDto?.dueDate,
                status: notiItem.status,
                style: stylesHTML.RED_BOLD,
              }),
            }}
          />
        </TextCM>
        <View style={styles.ctnText}>
          <TextCM
            style={[
              {
                fontFamily: Font.InterSemiBold600,
              },
              styles.text,
            ]}>
            {''}
          </TextCM>
          <TextCM
            style={[
              [
                {
                  fontFamily: Font.InterRegular400,
                },
                styles.text,
              ],
            ]}>
            {/* {content.notifyTime} */}
            {convertTime(notiContent.createdDateNotify)}
          </TextCM>
        </View>
        <Divider />
      </View>
    </TouchableOpacity>
  );
}
