import {useEffect, useState} from 'react';
import HeaderCM from '../../components/Header/HeaderCM';
import {useNotificationServices} from '../../../hooks/useNotificationServices';
import {useTranslation} from 'react-i18next';
import {FlatList} from 'react-native';
import NotificationCard from './NotificationCard';
import {Icon, Menu, MenuItem, TopNavigationAction} from '@ui-kitten/components';
import BottomSheetCM from '../../components/BottomSheet';
import TextCM from '../../components/Text';
import Toast from 'react-native-toast-message';
import {useETaskZutandStore} from '../../../zutand/eTaskZutandStore';

const NotificationScreen = () => {
  const NotificationService = useNotificationServices();
  const {totalNotify, listNotify, setTotalNotify, setListNotify} =
    useETaskZutandStore();
  const {t} = useTranslation();
  const [currPage, setCurrPage] = useState<number>(0);
  const [selectTab, setSelectTab] = useState<'unread' | 'read'>('unread');
  const [refreshing, setRefreshing] = useState(false);
  const [menuVisible, setMenuVisible] = useState(false);

  const getListNotification = async (currPage = 0, tab = 'unread') => {
    let dataNoti = await NotificationService.getListNotifications(
      {page: currPage, size: 10, sort: 'createdDate,desc'},
      {status: tab, system: 'E_TASK'},
    );
    if (currPage == 0) {
      setListNotify(dataNoti?.data || []);
    } else {
      setListNotify([...listNotify, ...dataNoti.data]);
    }
  };
  const fetchNextPage = async () => {
    const nextPage = currPage + 1;
    getListNotification(nextPage, selectTab);
    setCurrPage(nextPage);
  };
  const onRefresh = () => {
    getListNotification(0, selectTab);
    setCurrPage(0);
  };
  useEffect(() => {
    getListNotification();
  }, []);

  const changeSelectTab = async (tab: 'read' | 'unread') => {
    if (tab !== selectTab) {
      setRefreshing(true);
      await getListNotification(0, tab);
      setSelectTab(tab);
      setCurrPage(0);
      setMenuVisible(false);
      setRefreshing(false);
    }
  };

  const handleDirect = () => {
    // Xử lý khi bấm vào thông báo
  };

  const markAsReaded = async (notiId: number) => {
    let data = await NotificationService.markAsReadNotify(notiId);
    if (data !== 'ok') {
      Toast.show({
        type: 'error',
        text1: t('CM.error'),
      });
      return;
    }
    const rmedListNoti = listNotify.filter(no => no.id !== notiId);
    setListNotify(rmedListNoti);
    setTotalNotify(totalNotify - 1);
    handleDirect();
  };

  const renderAction = () => {
    return (
      <Menu>
        <MenuItem
          key={'read'}
          title={props => <TextCM {...props}>{t(`NT.navbar.read`)}</TextCM>}
          onPress={() => changeSelectTab('read')}
          accessoryRight={
            selectTab == 'read' ? <Icon name="checkmark" /> : undefined
          }
        />
        <MenuItem
          key={'unread'}
          title={props => <TextCM {...props}>{t(`NT.navbar.unread`)}</TextCM>}
          onPress={() => changeSelectTab('unread')}
          accessoryRight={
            selectTab == 'unread' ? <Icon name="checkmark" /> : undefined
          }
        />
      </Menu>
    );
  };

  const renderMenuAction = (): React.ReactElement => (
    <TopNavigationAction
      icon={<Icon fill={'#fff'} name="funnel-outline" />}
      onPress={() => setMenuVisible(true)}
    />
  );
  return (
    <>
      <HeaderCM
        title={t('NT.Notification')}
        renderContentRight={renderMenuAction}
      />
      <FlatList
        style={{paddingHorizontal: 10}}
        showsHorizontalScrollIndicator={false}
        showsVerticalScrollIndicator={false}
        data={listNotify}
        renderItem={({item}) => (
          <NotificationCard
            notiItem={{
              ...item,
              content: JSON.parse(item.content.toString()),
            }}
            tab={selectTab}
            markAsReaded={markAsReaded}
          />
        )}
        onEndReachedThreshold={0.5}
        onEndReached={fetchNextPage}
        refreshing={refreshing}
        onRefresh={onRefresh}
      />

      <BottomSheetCM
        title={t('CM.noti')}
        onClose={() => setMenuVisible(false)}
        isVisible={menuVisible}
        renderContent={renderAction()}
      />
    </>
  );
};

export default NotificationScreen;
